":"الفحوصات الأساسية لمتابعة صحتك وصحة الجنين","display_price":581,"old_price":775,"included_tests":["صورة دم كاملة","فصيلة الدم","عامل RH","سكر عشوائي","تحليل بول","فيروس بي HBs Ag","فيروس سي HCV","فيروس نقص المناعة HIV","هرمون الغدة الدرقية"],"image_path":"https://images.unsplash.com/photo-1555252333-9f8e92e65df9?w=600&h=400&fit=crop&q=80","display_order":40,"is_active":true,"is_published":true},{"title":"باقة القلب والضغط","description":"تقييم شامل لصحة القلب وعوامل الخطر القلبية","display_price":1088,"old_price":1450,"included_tests":["دهون كاملة","CRP عالي الحساسية","هوموسيستين","سكر صائم","سكر تراكمي","يوريا","كرياتينين","حمض البوليك","صورة دم كاملة"],"image_path":"https://images.unsplash.com/photo-1628348070889-cb656235b4eb?w=600&h=400&fit=crop&q=80","display_order":50,"is_active":true,"is_published":true}],"articles":[{"title":"أهمية الالتزام بشروط التحاليل الطبية","slug":"prep","excerpt":"ليه لازم تصوم أو تمتنع عن أدوية معينة قبل التحليل؟ وليه الشروط مهمة؟","body_json":{"text":"ليه الالتزام بشروط التحليل مهم؟ التحاليل الطبية هي أساس التشخيص السليم. لو الشروط مش متظبطة، النتيجة ممكن تطلع غلط وتأدي لتشخيص غلط أو علاج غلط. عشان كده، الالتزام بالشروط مش رفاهية، ده ضرورة. أمثلة على شروط مهمة: الصيام: تحاليل السكر والدهون محتاجة صيام 8-14 ساعة. الامتناع عن الأدوية: بعض الأدوية ممكن تغير نتائج التحاليل. الامتناع عن الكحول: الكحول بيأثر على وظائف الكبد والدهون. الراحة قبل التحليل: المجهود البدني الشديد ممكن يرفع إنزيمات العضلات والكبد. توقيت التحليل: بعض الهرمونات بتتغير على مدار اليوم. إيه اللي يحصل لو مش التزمت؟ النتيجة ممكن تطلع: عالية أو واطية بشكل غير طبيعي، مش واضحة، أو مضللة وتخلي الدكتور ياخد قرار غلط. نصيحة من معامل طيبة: دايمًا اسأل الدكتور أو الصيدلي عن شروط التحليل قبل ما تعمله. واحنا في معامل طيبة بنوضحلك كل الشروط لكل تحليل، عشان نضمنلك نتيجة دقيقة.","source":"مصادر: Mayo Clinic، MedlinePlus، MSD Manuals"},"author_name":"معامل طيبة","is_published":true},{"title":"أعراض نقص فيتامين د","slug":"vitd","excerpt":"إيه العلامات اللي تدل على نقص فيتامين د؟ وإيه التحاليل المطلوبة؟","body_json":{"text":"أعراض نقص فيتامين د: آلام العظام والمفاصل ضعف العضلات التعب والإجهاد المستمر تغيرات المزاج تساقط الشعر بطء التئام الجروح ضعف المناعة التحاليل المطلوبة: فيتامين د3 كالسيوم كلي فوسفور وظائف الكلى والكبد مين الأكثر عرضة للنقص؟ كبار السن اللي مش بيتعرضوا للشمس النساء الحوامل والمرضعات مرضى الكلى والكبد العلاج: التعرض للشمس 15-20 دقيقة يوميًا، الأطعمة الغنية بفيتامين د، والمكملات بعد استشارة الطبيب.","source":"مصادر: Mayo Clinic، MedlinePlus، MSD Manuals"},"author_name":"معامل طيبة","is_published":true},{"title":"أعراض ارتفاع السكر في الدم","slug":"diabetes","excerpt":"إيه العلامات اللي تدل على ارتفاع السكر؟ وإيه التحاليل المطلوبة؟","body_json":{"text":"أعراض ارتفاع السكر: العطش الشديد كثرة التبول التعب والإجهاد زغللة العين فقدان الوزن بطء التئام الجروح تنميل في الأطراف التحاليل المطلوبة: سكر صائم سكر عشوائي سكر تراكمي أنسولين صائم وظائف الكلى دهون كاملة نصيحة: لو عندك أي من الأعراض دي، متستناش. اعمل التحاليل فورًا، لأن التشخيص المبكر بيمنع المضاعفات.","source":"مصادر: Mayo Clinic، MSD Manuals"},"author_name":"معامل طيبة","is_published":true},{"title":"أعراض الأنيميا (فقر الدم)","slug":"anemia","excerpt":"إيه أعراض الأنيميا؟ وإيه التحاليل اللي بتكشفها؟","body_json":{"text":"أعراض الأنيميا: التعب والضعف العام شحوب الجلد ضيق التنفس الدوخة الصداع المستمر برودة اليدين والقدمين تساقط الشعر التحاليل المطلوبة: صورة دم كاملة حديد ومخزون الحديد سعة ارتباط الحديد فيتامين B12 حمض الفوليك","source":"مصادر: Mayo Clinic، MSD Manuals، MedlinePlus"},"author_name":"معامل طيبة","is_published":true},{"title":"أعراض قصور الغدة الدرقية","slug":"thyroid","excerpt":"إيه علامات خمول الغدة الدرقية؟ وإيه التحاليل المطلوبة؟","body_json":{"text":"أعراض قصور الغدة الدرقية: التعب والإرهاق زيادة الوزن الإمساك برودة الجسم جفاف الجلد والشعر بطء ضربات القلب الاكتئاب اضطرابات الدورة الشهرية التحاليل المطلوبة: هرمون الغدة الدرقية (TSH) هرمون T4 الحر هرمون T3 الحر أجسام مضادة للغدة","source":"مصادر: Mayo Clinic، MSD Manuals"},"author_name":"معامل طيبة","is_published":true},{"title":"أعراض ارتفاع إنزيمات الكبد","slug":"liver","excerpt":"إيه علامات مشاكل الكبد؟ وإيه التحاليل اللي بتكشفها؟","body_json":{"text":"أعراض ارتفاع إنزيمات الكبد: التعب والإرهاق فقدان الشهية الغثيان والقيء اصفرار الجلد والعينين ألم في البطن العلوي الأيمن بول داكن اللون حكة جلدية التحاليل المطلوبة: ALT و AST فوسفاتيز قلوي (ALP) إنزيم جاما (GGT) بيليروبين ألبيومين وبروتين كلي فيروسات الكبد B و C","source":"مصادر: Mayo Clinic، MSD Manuals"},"author_name":"معامل طيبة","is_published":true},{"title":"أعراض ارتفاع وظائف الكلى","slug":"kidney","excerpt":"إيه علامات مشاكل الكلى؟ وإيه التحاليل اللي بتكشفها؟","body_json":{"text":"أعراض ارتفاع وظائف الكلى: التعب والضعف العام تورم القدمين والكاحلين تغيرات في كمية البول رغوة في البول الغثيان والقيء حكة جلدية ارتفاع ضغط الدم التحاليل المطلوبة: يوريا كرياتينين معدل الترشيح (GFR) تحليل بول كامل ألبومين مجهري نصيحة: مرضى السكري وضغط الدم لازم يعملوا تحاليل وظائف الكلى بشكل دوري (كل 6-12 شهر).","source":"مصادر: Mayo Clinic، MSD Manuals"},"author_name":"معامل طيبة","is_published":true},{"title":"أعراض التهاب المسالك البولية","slug":"uti","excerpt":"إيه علامات التهاب المسالك؟ وإيه التحاليل المطلوبة؟","body_json":{"text":"أعراض التهاب المسالك البولية: حرقة عند التبول رغبة ملحة ومتكررة في التبول بول عكر أو له رائحة نفاذة دم في البول ألم في منطقة الحوض حمى وقشعريرة التحاليل المطلوبة: تحليل بول كامل مزرعة بول صورة دم كاملة بروتين سي التفاعلي (CRP)","source":"مصادر: Mayo Clinic، MSD Manuals"},"author_name":"معامل طيبة","is_published":true}],"faqs":[{"question":"إمتى هتستلم نتيجة التحليل؟","answer":"معظم التحاليل الروتينية في نفس اليوم. المتخصصة من 24-72 ساعة. المزارع من 3-5 أيام.","display_order":0,"is_published":true},{"question":"هل يوجد سحب من المنزل؟","answer":"نعم، سحب من المنزل متاح بالحجز المسبق ووفق مواعيد الخدمة المتاحة.","display_order":10,"is_published":true},{"question":"إيه طرق الدفع المتاحة؟","answer":"كاش أو محفظة إلكترونية.","display_order":20,"is_published":true},{"question":"هل لازم صيام قبل التحليل؟","answer":"بعض التحاليل فقط تحتاج صيام 8-12 ساعة. اضغط على زر \"!\" جنب أي تحليل لمعرفة شروطه بالتفصيل.","display_order":30,"is_published":true},{"question":"إيه الفرق بين الباقة والتحليل الفردي؟","answer":"الباقة توفر لك مجموعة تحاليل بسعر مخفض (خصم 25%)، بدل ما تحجز كل تحليل لوحده بالسعر الكامل.","display_order":40,"is_published":true}],"testimonials":[{"display_name":"أحمد م.","content":"خدمة ممتازة وسريعة. النتيجة وصلتني في نفس اليوم عبر واتساب، والتعامل كان محترم جداً. أنصح الجميع بمعامل طيبة.","rating":5,"display_order":0,"is_published":true},{"display_name":"محمود ع.","content":"أخذت باقة الفحص الشامل وكانت تجربة رائعة. الفريق محترف والأسعار مناسبة جداً. شكراً دكتور أحمد على المتابعة.","rating":5,"display_order":10,"is_published":true},{"display_name":"سارة أ.","content":"طلبت سحب من المنزل، وجاؤوا في الميعاد بالظبط. التحاليل كانت دقيقة والأسعار شفافة بدون رسوم خفية. تجربة احترافية.","rating":5,"display_order":20,"is_published":true},{"display_name":"نورهان م.","content":"باقة تساقط الشعر ساعدتني أعرف سبب المشكلة. بعد ما عملت التحاليل وبدأت العلاج، شعري رجع أحسن من الأول. شكراً معامل طيبة.","rating":5,"display_order":30,"is_published":true},{"display_name":"خالد إ.","content":"المكان نظيف والأجهزة حديثة. النتائج مضمونة ودقيقة. الأمانة والشفافية في التعامل معاهم حاجة مميزة.","rating":5,"display_order":40,"is_published":true},{"display_name":"فاطمة ح.","content":"عملت باقة متابعة الحمل عندهم، وكانت تجربة مريحة جداً. الدكتور أحمد متابع معايا خطوة بخطوة. ربنا يبارك فيهم.","rating":5,"display_order":50,"is_published":true}],"offers":[{"title":"خصم خاص بمناسبة إطلاق الموقع","description":"خصم 20% على التحاليل خلال فترة العرض المحددة في الموقع القديم.","discount_percent":20,"starts_at":"2026-10-01T00:00:00+02:00","ends_at":"2026-10-31T23:59:59+02:00","is_active":false,"is_published":true}]}$payload$::jsonb;
begin
 select id into v_tenant_id from public.tenants where slug='teba-labs' limit 1;
 if v_tenant_id is null then raise exception 'Taiba tenant slug teba-labs was not found; import aborted.'; end if;
 insert into public.site_settings(tenant_id,public_content,theme_json) values(v_tenant_id,v_payload->'content',jsonb_build_object('accent','#16877f','primary_color','#16877f')) on conflict(tenant_id) do nothing;
