 'footer_text',coalesce(nullif(s.public_content->>'footer_text',''),v_payload#>>'{content,footer_text}'),
 'branch_hours_text',coalesce(nullif(s.public_content->>'branch_hours_text',''),v_payload#>>'{content,branch_hours_text}'),
 'trust_badges',coalesce(s.public_content->'trust_badges',v_payload#>'{content,trust_badges}'),
 'stats',coalesce(s.public_content->'stats',v_payload#>'{content,stats}')
 ),updated_at=now() where s.tenant_id=v_tenant_id;
 insert into public.site_sections(tenant_id,section_key,title,content,layout_key,display_order,is_visible,is_published)
 select v_tenant_id,x.section_key,x.title,x.content,x.layout_key,x.display_order,x.is_visible,x.is_published from jsonb_to_recordset(v_payload->'sections') as x(section_key text,title text,content jsonb,layout_key text,display_order integer,is_visible boolean,is_published boolean) on conflict(tenant_id,section_key) do nothing;
 insert into public.site_test_catalog(tenant_id,code,display_name,category,description,display_price,display_order,is_visible,is_published)
 select v_tenant_id,x.code,x.display_name,x.category,nullif(x.description,''),x.display_price,x.display_order,x.is_visible,x.is_published from jsonb_to_recordset(v_payload->'tests') as x(code text,display_name text,category text,description text,display_price numeric,display_order integer,is_visible boolean,is_published boolean) on conflict(tenant_id,code) do nothing;
 insert into public.site_packages(tenant_id,title,description,display_price,old_price,included_tests,image_path,display_order,is_active,is_published)
 select v_tenant_id,x.title,x.description,x.display_price,x.old_price,x.included_tests,x.image_path,x.display_order,x.is_active,x.is_published from jsonb_to_recordset(v_payload->'packages') as x(title text,description text,display_price numeric,old_price numeric,included_tests jsonb,image_path text,display_order integer,is_active boolean,is_published boolean) where not exists(select 1 from public.site_packages p where p.tenant_id=v_tenant_id and p.title=x.title);
 insert into public.site_articles(tenant_id,title,slug,excerpt,body_json,author_name,is_published,published_at)
 select v_tenant_id,x.title,x.slug,x.excerpt,x.body_json,x.author_name,x.is_published,now() from jsonb_to_recordset(v_payload->'articles') as x(title text,slug text,excerpt text,body_json jsonb,author_name text,is_published boolean) on conflict(tenant_id,slug) do nothing;
 insert into public.site_faqs(tenant_id,question,answer,display_order,is_published)
 select v_tenant_id,x.question,x.answer,x.display_order,x.is_published from jsonb_to_recordset(v_payload->'faqs') as x(question text,answer text,display_order integer,is_published boolean) where not exists(select 1 from public.site_faqs f where f.tenant_id=v_tenant_id and f.question=x.question);
 insert into public.site_testimonials(tenant_id,display_name,content,rating,display_order,is_published)
 select v_tenant_id,x.display_name,x.content,x.rating,x.display_order,x.is_published from jsonb_to_recordset(v_payload->'testimonials') as x(display_name text,content text,rating smallint,display_order integer,is_published boolean) where not exists(select 1 from public.site_testimonials t where t.tenant_id=v_tenant_id and t.display_name=x.display_name and t.content=x.content);
 insert into public.site_offers(tenant_id,title,description,discount_percent,starts_at,ends_at,is_active,is_published)
 select v_tenant_id,x.title,x.description,x.discount_percent,x.starts_at,x.ends_at,x.is_active,x.is_published from jsonb_to_recordset(v_payload->'offers') as x(title text,description text,discount_percent numeric,starts_at timestamptz,ends_at timestamptz,is_active boolean,is_published boolean) where not exists(select 1 from public.site_offers o where o.tenant_id=v_tenant_id and o.title=x.title and o.starts_at=x.starts_at);
 insert into public.site_branch_profiles(tenant_id,branch_id,public_name,public_address,public_phone,public_map_link,display_order,show_on_site,is_published)
 select v_tenant_id,b.id,b.name,b.address,coalesce(nullif(b.phone,''),v_payload#>>'{content,phone_display}'),b.map_link,row_number() over(order by b.created_at,b.id)*10,true,true from public.branches b where b.tenant_id=v_tenant_id and b.is_active on conflict(tenant_id,branch_id) do nothing;
end $import$;
